from pathlib import Path
import json,collections,subprocess,shutil,gzip,tarfile,hashlib
W=Path('/tmp/family5-alternating');OUT=Path('/workspace/family5-alternating-report');R=Path('/tmp/family5-land')
assert json.loads((W/'finished.json').read_text())['complete']
history=json.loads((W/'historical-runs.json').read_text());new=json.loads((W/'new-runs.json').read_text());rows=history+new
assert len(new)==5 and [r['side'] for r in new]==['c02','main','c02','main','main']
assert collections.Counter(r['side'] for r in rows)=={'c02':4,'main':4}
summary=json.loads((W/'artifact-summary.json').read_text());manifest=json.loads((W/'artifact-manifest.json').read_text());support=json.loads((W/'support-comparison.json').read_text());maps=json.loads((W/'source-map-explanation.json').read_text());info=json.loads((W/'build-info-explanation.json').read_text())
assert summary['javascript_all_identical'] and not support['external_dependency_differences']
assert all(not json.loads(p.read_text())['javascript_differences_from_initial_snapshot'] for p in W.glob('run-*/artifact-validation.json'))
API='unittests:: Public APIs for typescript.d.ts should be acknowledged when they change'
def brief(f):
 t=f['title']
 if t==API:name='API'
 elif 'codeFixClassImplementInterfaceNoTruncation.ts' in t:name='NoTruncation body'
 elif 'relationComplexityError.ts' in t:name='relationComplexityError before-all'
 elif 'recursiveConditionalTypes.ts' in t:name='recursiveConditionalTypes before-all'
 elif 'templateLiteralTypes1.ts' in t:name='templateLiteralTypes1 before-all'
 else:name=t
 return name+' '+('unobserved' if f.get('elapsed_ms') is None else f"{f['elapsed_ms']/1000:.3f}s")
# Verify the unchanged launch observer and wrapper scripts at both tested repository shas.
executors=[]
for file in ['stage3/lane/run.py','stage3/oracle/run.py','stage3/oracle/observe-errors.cjs']:
 a=subprocess.check_output(['git','show','fbe5b72b:'+file],cwd=R);b=subprocess.check_output(['git','show','28a2e220:'+file],cwd=R);assert a==b
 executors.append({'file':file,'byte_identical':True,'bytes':len(a),'sha256':hashlib.sha256(a).hexdigest()})
(W/'executor-comparison.json').write_text(json.dumps(executors,indent=2)+'\n')
(W/'all-runs.json').write_text(json.dumps(rows,indent=2)+'\n')
aggregates={s:{'records':sum(r['side']==s for r in rows),'green':sum(r['side']==s and r['exit_code']==0 for r in rows),'red':sum(r['side']==s and r['exit_code']!=0 for r in rows)} for s in ['c02','main']}
(W/'summary.json').write_text(json.dumps({'javascript_code_identical':True,'javascript_files_compared':19,'all_artifacts_compared':1499,'non_javascript_differences':18,'new_runs_all_green':all(r['exit_code']==0 for r in new),'aggregates':aggregates,'pushed':False,'committed':False,'historical_concurrent_run':'C02-earlier-1'},indent=2)+'\n')
lines=['# C02/main: executable bytes and alternating lane runs','', '**All 19 JavaScript bundles are byte-identical. All five new lane runs are green: 106,366 passing, one sanctioned failure, real lane exit 0. Nothing was committed or pushed.**','', 'Main: `fbe5b72ba115a8f3060d4b5229fd578574f4505f`. C02: `28a2e22015d0cf51667fcefa7acb246cab553817`. Both use TypeScript v6.0.3, `050880ce59e30b356b686bd3144efe24f875ebc8`.','', '## The lane actually executes','', 'The checked-in chain is `stage3/lane/run.sh` → lane/run.py → oracle/run.sh → oracle/run.py. The oracle runs `npm run build` and then `npm test -- --workers=8 --lint=false --no-colors`. package.json selects `hereby runtests-parallel --light=false`. Herebyfile.mjs:532 names `./built/local/run.js`; scripts/build/tests.mjs:133 passes that bundle to Node, and src/testRunner/parallel/host.ts:286 forks `process.argv[1]` for the eight workers. Thus the host and each worker execute the same **run.js**, which bundles the compiler, harness and test-runner code. There is no separate harness.js bundle.','', 'The local compiler/server loaders and their payloads are included below: tsc.js→_tsc.js; tsserver.js→_tsserver.js; typingsInstaller.js→_typingsInstaller.js; tsserverlibrary.js→typescript.js; watchGuard.js is covered too. The nine tracked last-known-good lib/*.js bundles are included as well. Herebyfile.mjs:194 emits linked source maps with sourcesContent:false and external packages.','', 'Beyond the bundles, all six compared launch/build support files match, and **4,776 external JavaScript/native/config dependency files match byte for byte**. The stage3 lane/oracle/observer scripts also match at the two repository shas. See [support comparison](support-comparison.json) and [executor comparison](executor-comparison.json).','', '## Executable byte comparison','', 'Primary inputs: the untouched original C02 full-lane tree `/workspace/family5-c02-lane/adapted-tree` and the completed main control `/workspace/family5-main-lane-alone/adapted-tree`. The C02 tree used here was not modified by subsequent targeted tests or shared-path input selection. Direct byte equality was tested, not just hash equality. The full [1,499-file manifest](artifact-manifest.json) includes every regular file below built/local and lib. There are no missing files between sides.','', '| JavaScript file | Bytes on each side | Result |','|---|---:|---|']
for r in manifest:
 if r['file'].endswith(('.js','.mjs','.cjs')):lines.append(f'| `{r["file"]}` | {r["main_bytes"]:,} | identical |')
lines+=['', '**The executable JavaScript code under test is identical. There is no C02 JavaScript implementation delta to explain red versus green; the fresh alternating sequence supports execution nondeterminism/order as the explanation for the earlier reds.** This statement concerns executable code. The build directories contain the 18 non-executable differences below. Public typescript.d.ts, standard-library declarations and the other 1,481 artifacts match. Every new run\'s 19 JavaScript files was also re-hashed after execution and matched this initial snapshot.','', '## Every differing artifact','', 'Offsets are zero-based byte offsets. Both sizes are in bytes. [Hunks for every file](artifact-hunks.md) show the exact first changed context; declaration files have unified source hunks.','', '| File | Main bytes | C02 bytes | First different byte |','|---|---:|---:|---:|']
for r in summary['differing_files']:lines.append(f'| `{r["file"]}` | {r["main_bytes"]} | {r["c02_bytes"]} | {r["first_difference_offset_0based"]} |')
lines+=['', 'The differences are completely characterized:','', '- **Two internal declaration files** gain the requested internal optional Node callable. Public typescript.d.ts stays identical.','- **Three JavaScript source maps** differ only in mappings. Decoding confirms identical generated coordinates, source paths and symbol names; references into compiler/types.ts move by **+1 source line**, with no column or name change. Changed segment counts: _tsc.js.map 2,319; run.js.map 5,655; typescript.js.map 5,580.','- **One declaration source map**, compiler/types.d.ts.map, records that added member.','- **Twelve tsbuildinfo files** differ only in SHA-256 source/declaration hashes; every changed JSON leaf is a hash. There is no embedded-path delta.','', '[Decoded map explanation](source-map-explanation.json), [every changed build-info field](build-info-explanation.json), and the complete [artifact hunks](artifact-hunks.md). Source maps can be read for error-stack reporting; they are not claimed to be identical.','', 'The declaration hunk is:','', '```diff','     /** @internal */ emitNode?: EmitNode | undefined;','+    /** @internal */ getPositionOfLineAndCharacter?: ((line: number, character: number, allowEdits?: true) => number) | undefined;',' }','```','', '## Four recorded lanes per side','', 'There were **two earlier C02 lanes and one earlier main lane**, not two main lanes. The requested fresh order **C02, main, C02, main** was run exactly. One additional final main control makes the requested totals **four C02 and four main records**. The initial historical C02 run is explicitly marked concurrent; it is not an idle-box measurement. All five new runs were sequential and alone on the same box, with eight workers, the standard 40,000 ms test/hook timeout, no test filter, all runners, and Node v24.19.0. No product test or census ran alongside them. Pre-run process snapshots and exact commands are retained per run.','', '| Record | Side | Conditions | Passing | Failing | Pending | Real lane exit | Every failure, seconds |','|---|---|---|---:|---:|---:|---:|---|']
for r in rows:
 cond='CONCURRENT historical' if 'concurrent' in r['context'] else 'idle historical' if 'earlier' in r['id'] else 'idle; extra count control' if r['id']=='new-5' else 'idle; requested alternation'
 c=r['counts'];lines.append(f'| {r["id"]} | {r["side"]} | {cond} | {c["passing"]} | {c["failing"]} | {c["pending"]} | **{r["exit_code"]}** | '+ '; '.join(brief(f) for f in r['failures'])+' |')
lines+=['', 'API = `unittests:: Public APIs for typescript.d.ts should be acknowledged when they change`, the sanctioned baseline-content failure. All npm test children exited 1 because this failure is expected; the validated lane exits 0 only when the exact required counts and sanctioned failure match. [All run records](all-runs.json) retain the individual install/build/test phase exits and durations.','', 'The first historical C02 hook failure skipped six suite bodies and added one failed hook: net five missing reported results. The second historical C02 run lost two such suites: net ten. All new runs report the full **106,367** total.','', '## Every failure: exact case or hook name and observed time','']
for r in rows:
 lines+=['', '### '+r['id']+' ('+r['side']+')','']
 for f in r['failures']:
  elapsed='not observed' if f.get('elapsed_ms') is None else f'{f["elapsed_ms"]:.6f} ms'
  lines.append('- `'+f['title']+'` — '+elapsed+'; cause `'+str(f.get('cause'))+'`'+('; timeout '+str(f['timeout_ms'])+' ms' if f.get('cause')=='timeout' else '')+'.')
lines+=['', '## Interpretation and measurement notes','', 'New C02 results: **two green out of two**. New main results: **three green out of three**. Including the requested earlier records, C02 is **two green/two red** (one red was concurrent), and main is **four green/zero red**. The earlier C02 reds did not reproduce in the requested alternating sequence. The JavaScript identity is established independently of the timing observations; this small series does not identify a particular scheduler, GC or cache mechanism.','', 'All five fresh output trees began without .parallelperf.json and without mytest.config; their scheduling-input snapshots are retained. Each output was fresh. After a run ended, complete logs/reports and all built-artifact hashes were preserved before its generated tree was removed to keep space available. The two original comparison trees remain available at the paths above.','', 'An environment-context refresh terminated the original coordinator during new-2, while its independently sessioned main lane continued and completed. Its real exit **0** was recovered from the retained kernel wait status of the unique session-leader process PID 65310, started at the recorded run time. [Raw exit recovery](run-2-main/exit-recovery.json) preserves /proc/PID/stat field 52 and its decoding; the exit was not inferred from the green verdict. The lane\'s internal wall time is used for that record because the parent wall clock was lost. There was an idle gap before new-3 while the coordinator was recovered. The resumed coordinator was detached and recorded durable child PIDs. No two lane workloads overlapped.','', 'No adaptations, ledger entries, internal/ code, test timeouts or worker counts were changed. **No commits or pushes were made.** The worktree was restored to its original commit 16fbb39cdeaefa79e9f23b3ab0f02cf8a32ad365. This report and its evidence are local only.']
(W/'REPORT.md').write_text('\n'.join(lines)+'\n')
# Preserve earlier receipt metadata without copying their generated source trees.
for r in history:
 src=Path(r['folder']);target=W/'history'/r['id'];target.mkdir(parents=True,exist_ok=True)
 for rel in ['report.json','execution.json','oracle/report.json','oracle/tests.log']:
  p=src/rel
  if p.exists():to=target/rel;to.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,to)
for p in list(W.rglob('*')):
 if p.is_file() and p.suffix in ['.log','.jsonl','.diff']:
  with p.open('rb') as src,gzip.GzipFile(filename=str(p)+'.gz',mode='wb',mtime=0) as dst:shutil.copyfileobj(src,dst)
  p.unlink()
assert not OUT.exists();shutil.copytree(W,OUT)
with tarfile.open('/workspace/family5-alternating-report.tar.gz','w:gz') as t:t.add(OUT,arcname=OUT.name)
print('REPORT',OUT/'REPORT.md');print('AGGREGATES',aggregates);print('BYTE COMPARISON: 19 JavaScript files identical; 18 non-JavaScript differences listed with sizes/offsets/hunks.');print('NO COMMITS OR PUSHES')
